// New screens register in one post-render registry rather than extending the render chain per feature.
const farmViews=new Set();
const renderCore=render;
render=function(){renderCore();for(const view of farmViews)view()};
const foodOptions={tomato:'🍅 Томаты',cucumber:'🥒 Огурцы',greens:'🌿 Зелень',carrot:'🥕 Морковь',pepper:'🫑 Перцы',courgette:'🥒 Кабачки'};
function chooseFoodPlan(){
 if(!account)return profile();const p=lifeData?.preferences||{};
 formAsync('🦊 Что вы хотите к столу?',`<p>Вы выбираете овощи, а садовник подбирает подходящий сезон и план выращивания.</p><div class="food-choice-grid">${Object.entries(foodOptions).map(([id,name])=>`<label class="food-choice"><input type="checkbox" name="food" value="${id}" ${(p.food_choices||[]).includes(id)?'checked':''}><span>${name}</span></label>`).join('')}</div><label>Как участвовать<select name="mode"><option value="together">Решать вместе с садовником</option><option value="managed">Поручить заботу садовнику</option><option value="manual">Самому выбирать работы</option></select></label><label>Куда отправить урожай<select name="destination"><option value="home">🚚 Домой</option><option value="storage">📦 На мой склад</option><option value="gift">🎁 Подарить близким</option></select></label><p>Сохраним пожелания. Работы и услуги оплачиваются только после отдельного выбора и согласования.</p><button class="btn">Сохранить мою корзину мечты</button>`,async f=>{await api('life-food-plan',{foods:f.getAll('food'),mode:f.get('mode'),destination:f.get('destination')});await loadLife();toast('Пожелания сохранены для вашего хозяйства')});
 document.querySelector('#fields [name=mode]').value=p.care_mode||'together';document.querySelector('#fields [name=destination]').value=p.harvest_destination||'home';
}
function nextGardenStep(p){
 const orders=(opsData?.orders||[]).filter(o=>o.plot_id===p.id&&!['done','cancelled'].includes(o.status));
 if(orders.length)return {icon:'👩‍🌾',title:'Садовник на связи',text:'Посмотрите согласование, время и результат работы.',tab:'activity'};
 const map={unchecked:['🔎','Познакомимся с грядкой','Сначала садовник проверит участок.'],empty:['🪏','Подготовим землю','Следующий шаг — подготовка почвы.'],ready:['🌱','Выберем посадки','Почва готова. Согласуйте овощи и план ухода.'],planted:['🌱','Первые ростки впереди','Наблюдайте за посадками. Уход — по плану садовника.'],growing:['🌿','Растём к вашей корзине','Не нужно поливать ради баллов: всё по потребности растений.'],harvest_ready:['🧺','Пора собирать!','Закажите сбор и выберите, куда отправить урожай.'],finished:['🍂','Сезон завершён','Можно согласовать новый цикл посадки.']};
 const [icon,title,text]=map[p.growing_state]||map.unchecked;return {icon,title,text,tab:p.growing_state==='harvest_ready'?'harvest':'grow'};
}
function gardenJourney(){if(!account)return profile();const plots=myPlots(),prefs=lifeData?.preferences||{};formAsync('🦊 Путь к вашей корзине',`<div class="journey-banner"><span>🧺</span><div><h3>Свои овощи — с заботой садовника</h3><p>${(prefs.food_choices||[]).map(id=>foodOptions[id]).join(' · ')||'Начнём с того, что вы любите есть.'}</p></div></div><button type="button" class="btn" onclick="modal.close();chooseFoodPlan()">🥗 Выбрать овощи</button><div class="journey-road">${[['🌱','Выберите грядку','Размер участка и срок аренды.'],['👩‍🌾','Согласуйте заботу','Садовник предложит план и стоимость.'],['📹','Наблюдайте за ростом','Камера, фотографии и история работ.'],['🧺','Получите урожай','Сбор, проверка партии и корзина домой.']].map(([icon,title,text],i)=>`<article><span>${icon}</span><div><small>ШАГ ${i+1}</small><h3>${title}</h3><p>${text}</p></div></article>`).join('')}</div>${plots.length?plots.map(p=>{const step=nextGardenStep(p);return `<button type="button" class="journey-plot" onclick="modal.close();openFarmBed(${p.id},'${step.tab}')"><span>${step.icon}</span><div><b>${esc(p.name)}</b><strong>${step.title}</strong><small>${step.text}</small></div><span>›</span></button>`}).join(''):'<a class="btn" href="#rent" onclick="modal.close()">🌱 Взять первую грядку</a>'}<p class="note">Рост и урожай подтверждает ферма. Игровое оформление не ускоряет реальные растения.</p>`,async()=>{})}
farmViews.add(()=>{
 document.querySelector('.garden-guide')?.remove();
 if(account&&((location.hash||'#home')==='#home'||currentRoomPlot())){const button=document.createElement('button');button.className='garden-guide';button.innerHTML='<span>🦊</span><b>К моей корзине</b>';button.onclick=gardenJourney;button.setAttribute('aria-label','Открыть помощника: путь к моей корзине');document.body.append(button)}
 if(account?.role==='admin'&&location.hash==='#farmer')document.querySelector('#app')?.insertAdjacentHTML('afterbegin','<button class="btn light" onclick="farmCostPreview()">🧮 Рассчитать стоимость работы</button>');
 if(account&&location.hash==='#settings')document.querySelector('#app')?.insertAdjacentHTML('beforeend',`<section class="panel"><h2>🌳 Кто видит моё хозяйство</h2><p>На карте видны название, количество грядок и стадии роста. Камеры, баланс и доставка остаются личными.</p><button class="btn light" onclick="setFarmVisibility(false)">Скрыть с общей карты</button> <button class="btn light" onclick="setFarmVisibility(true)">Показывать на карте</button></section>`);
 const p=currentRoomPlot();if(p){const hero=document.querySelector('.room-hero');const next=nextGardenStep(p);hero?.insertAdjacentHTML('afterend',`<aside class="garden-next" role="status"><span>${next.icon}</span><div><strong>${next.title}</strong><p>${next.text}</p></div></aside>`)}
});
render();

async function setFarmVisibility(visible){try{const result=await api('my-farm',{visible});if(!result.farm)throw Error('Сначала задайте название хозяйства');toast(visible?'Хозяйство видно на карте':'Хозяйство скрыто от других пользователей')}catch(e){toast(e.message)}}

function farmCostPreview(){formAsync('🧮 Экономика работы','<p>Зарплата 3 000 ₽ за смену 09:00–19:00. Отдельно учтите перерывы, подготовку, дорогу и отчёт.</p><label>Всего минут на заказ<input name="minutes" type="number" value="60" min="1" required></label><label>Продуктивных минут в смене<input name="productiveMinutes" type="number" value="420" min="1" max="600" required></label><label>Материалы, ₽<input name="materials" type="number" value="0" min="0"></label><label>Прочие расходы, ₽<input name="overhead" type="number" value="0" min="0"></label><label>Доход платформы<select name="marginMode"><option value="markup">30% сверху себестоимости</option><option value="margin">30% от конечной цены</option></select></label><div id="cost-preview" role="status"></div><button type="button" class="btn" onclick="calculateFarmCost()">Рассчитать</button>',async()=>{})}
async function calculateFarmCost(){const f=new FormData(document.getElementById('form'));try{const q=await api('service-price-preview',{minutes:Number(f.get('minutes')),productiveMinutes:Number(f.get('productiveMinutes')),materials:Math.round(Number(f.get('materials'))*100),overhead:Math.round(Number(f.get('overhead'))*100),marginMode:f.get('marginMode')});document.getElementById('cost-preview').innerHTML=`<h3>Цена: ${money(q.price_kopecks)}</h3><p>Труд: ${money(q.labor_kopecks)} · вся себестоимость: ${money(q.cost_kopecks)}.</p><p>Расчёт предварительный. Тариф меняется отдельно после проверки затрат.</p>`}catch(e){document.getElementById('cost-preview').textContent=e.message}}
